```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss;

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

Map<String, double> calculateAverageProfitLoss(List<Transaction> transactions) {
  Map<String, double> coinStats = {};

  for (Transaction transaction in transactions) {
    if (coinStats.containsKey(transaction.coinName)) {
      coinStats[transaction.coinName] += transaction.profitLoss;
    } else {
      coinStats[transaction.coinName] = transaction.profitLoss;
    }
  }

  return coinStats;
}

List<dynamic> getTopCoins({required List<Transaction> transactions, required bool isProfit}) {
  Map<String, double> avgProfitLoss = calculateAverageProfitLoss(transactions);
  List<MapEntry<String, double>> sortedEntries = avgProfitLoss.entries.toList();
  sortedEntries.sort((a, b) {
    double diff = isProfit ? b.value : a.value;
    return diff * -1;
  });

  int numTopCoins = 3;
  return List.from(sortedEntries.take(numTopCoins));
}

